/* Restored runtime-state CSS.
   The Instatic HTML importer prunes any selector whose classes are not present in the DOM
   at import time, which is exactly the set of classes applied later by JavaScript: the
   drawer/menu open state, the burger-to-X animation, the nav's scrolled "solid" state, the
   scroll lock, and the reveal system. Without these the burger toggles a class that has no
   styling and the menu never appears. */

body.is-locked { overflow:hidden }

.wz-ready [data-anim="hide"] { visibility:visible }

.nav.solid { background:rgba(250,248,243,.9);backdrop-filter:blur(14px);border-bottom-color:rgba(138,126,78,.26) }

.nav[data-journey="1"].solid .nav-links { opacity:0;pointer-events:none }

.nav[data-journey="1"].solid .nav-chapter { opacity:1 }

.burger.open span:nth-child(1) { transform:translateY(3.5px) rotate(45deg) }

.burger.open span:nth-child(2) { transform:translateY(-3.5px) rotate(-45deg) }

.nav.menu-open { z-index:130;background:transparent;backdrop-filter:none;
      border-bottom-color:transparent }

.nav.menu-open .nav-slot { opacity:0;pointer-events:none }

.nav.menu-open .nav-cta { opacity:0;pointer-events:none }

.nav.menu-open .nav-progress { opacity:0;pointer-events:none }

.nav.menu-open .nav-close { opacity:1 }

.nav.menu-open .burger span { background:#fff }

.drawer.open { clip-path:circle(150% at calc(100% - 42px) 42px) }

.drawer.open .dr-col li a { transform:translateY(0) }

.drawer.open .dr-col:nth-child(1) li a { transition-delay:.10s }

.drawer.open .dr-col:nth-child(2) li a { transition-delay:.16s }

.drawer.open .dr-col:nth-child(3) li a { transition-delay:.22s }

.drawer.open .dr-col:nth-child(4) li a { transition-delay:.28s }

.drawer.open .dr-col:nth-child(5) li a { transition-delay:.34s }

.pk-ba input[type=range] { position:absolute;inset:0;width:100%;height:100%;z-index:5;margin:0;
  opacity:0;cursor:ew-resize }

.wz-kit [data-rv] { opacity:0 }

.of .of-flag { font-size:.72rem;color:var(--fg-soft);font-weight:400;line-height:1.55;
      border-left:2px solid var(--rule);padding-left:.75rem }

.ch-reality .big .wz-word { color:rgba(20,20,22,.2) }

.ch-specialist .grid { display:grid;grid-template-columns:1fr;gap:clamp(2.5rem,5vw,5rem);align-items:start }

.cmp .tag.b { left:1rem;background:rgba(11,11,12,.72);color:#fff }

.cmp .tag.a { right:1rem;background:var(--gold-ink);color:#fff }

.ga-empty { color:var(--fg-soft);font-weight:400 }

/* ---- burger bars ----
   The two <span> bars cannot exist in the DOM: Instatic's button module rejects child
   nodes, so the importer stripped them and the control rendered blank. Drawn as
   pseudo-elements instead; .burger is already position:relative. */
.burger::before, .burger::after {
  content: ""; position: absolute; left: 10px; width: 24px; height: 1.5px;
  background: var(--fg); transition: transform .45s cubic-bezier(.22,1,.36,1);
}
.burger::before { top: 18px }
.burger::after  { top: 25px }
.burger.open::before { transform: translateY(3.5px) rotate(45deg) }
.burger.open::after  { transform: translateY(-3.5px) rotate(-45deg) }
.nav.menu-open .burger::before, .nav.menu-open .burger::after { background: #fff }

/* ba-drag-surface ---- before/after sliders ----
   Instatic rewrites the range input to type="text"; hide that stray box and make the
   figure itself the drag surface (the JS gives it role="slider" and a tabindex). */
.pk-ba input { display: none !important }
.pk-ba { cursor: ew-resize; touch-action: pan-y }
.pk-ba:focus-visible { outline: 2px solid var(--gold-light); outline-offset: 3px }


/* === Restored: rules the publish pipeline purges from the main sheet ===
   These were part of the shared stylesheet; after the 2026-08-13 registry
   dedupe the publish purge started dropping them, so they live here. */
.pk-ba .ba-tag.a {
  right: 0.7rem;
  background: var(--gold-ink);
  color: rgb(255, 255, 255);
}
.pk-ba .ba-tag.b {
  left: 0.7rem;
  background: rgba(11, 11, 12, 0.78);
  color: rgb(255, 255, 255);
}
@media (max-width: 679px) {
  .nav .nav-cta { display: none; }
}
@media (max-width: 719px) {
  .pg-hero .btn { flex: 1 1 auto; }
}
@media (min-width: 900px) {
  .pk-split.rev .sp-fig { order: 2; }
}
footer.foot .grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: clamp(2rem, 4vw, 3rem);
}
@media (min-width: 720px) {
  footer.foot .grid { grid-template-columns: 1.6fr 1fr 1fr 1.2fr; }
}

/* ==========================================================================
   THIN ARCH — the FP1 / FP2 / FP3 explainer (added 2026-08-18)
   Renders inside the home page's Chapter 06 (with .ta-inset) and as its own
   band on /all-on-4. Paints from the theme tokens only, so it does not assume
   the ground it sits on.

   FP1 is the only card given gold: that is the point the client asked the site
   to make, and it is made by emphasis rather than by disparaging FP3, which is
   the correct answer where bone loss is advanced.
   ========================================================================== */
.ta-inset { border-top: 1px solid var(--line); }
.ta .ta-head { display: grid; gap: 1rem; max-width: 52ch; margin-bottom: clamp(2rem, 4vw, 3rem); }
.ta .ta-title { font-size: var(--h2); font-family: var(--f-display); font-weight: 500; }
.ta .ta-head p { color: var(--fg-body); font-weight: 400; }

.ta-grid { display: grid; grid-template-columns: 1fr; gap: clamp(1rem, 1.8vw, 1.5rem); }
@media (min-width: 820px) { .ta-grid { grid-template-columns: repeat(3, 1fr); } }

.ta-card {
  background: var(--card);
  border: 1px solid var(--line);
  border-top: 3px solid var(--line-strong);
  padding: clamp(1.5rem, 2.6vw, 2.25rem);
  display: grid; gap: .85rem; align-content: start;
}
.ta-card.ta-fp1 { border-top-color: var(--rule); background: var(--bg-3); }
.ta-card.ta-fp2 { border-top-color: var(--line); }
.ta-card.ta-fp3 { border-top-color: var(--line-strong); }

.ta-key {
  font-family: var(--f-display); font-size: calc(2.1rem * var(--t-mid));
  font-weight: 500; line-height: 1; color: var(--fg-faint);
}
.ta-card.ta-fp1 .ta-key { color: var(--accent-lg); }
.ta-card h3 { font-family: var(--f-display); font-size: calc(1.35rem * var(--t-sm)); font-weight: 500; color: var(--fg); }

.ta-list { list-style: none; margin: 0; padding: 0; display: grid; gap: .6rem; }
.ta-list li { position: relative; padding-left: 1.4rem; color: var(--fg-body); font-weight: 300; font-size: .95rem; line-height: 1.55; }
.ta-list li::before { content: ""; position: absolute; left: 0; top: .55em; width: .5rem; height: .5rem; border-radius: 50%; background: var(--line-strong); }
.ta-card.ta-fp1 .ta-list li::before { background: var(--rule); }

/* The client's own diagram. Boxed rather than bled, because it arrives with its
   own blue/orange/red key that is not the brand palette and should read as a
   quoted reference figure rather than as site furniture. */
.ta-fig { margin: clamp(1.75rem, 3.5vw, 2.75rem) 0 0; padding: clamp(1rem, 2vw, 1.75rem); background: var(--bg); border: 1px solid var(--line); }
.ta-fig img { display: block; width: 100%; height: auto; }
.ta-fig figcaption { margin-top: 1rem; font-size: .74rem; letter-spacing: .12em; text-transform: uppercase; color: var(--fg-soft); }

.ta-note { margin-top: clamp(1.5rem, 3vw, 2.25rem); max-width: 62ch; color: var(--fg-body); font-weight: 300; }

/* ==========================================================================
   META PAIRS MUST STACK WITHOUT THE GRID (added 2026-08-18)
   The label/value pairs in the hero metas rely on their PARENT being
   display:grid to put the <b> above the <span>. Wherever that one declaration
   is lost, the pair renders inline and reads as
   "D.D.S., M.S.Diplomate, Am. Board of Prosthodontics" — which is exactly what
   the client reported as a typo on the home page. Making the children
   block-level as well means the pair survives the grid being dropped.
   ========================================================================== */
.ch-arrival .meta b, .ch-arrival .meta span { display: block; }
.pg-hero .ph-meta b, .pg-hero .ph-meta span { display: block; }

/* --------------------------------------------------------------------------
   REVIEW CARDS (restored 2026-08-18)
   .rv-head / .rv-score / .rv-grid / .rv-stars / .rv-av / .rv-more / .rv-play
   all survived the original import, but every .rv-card rule was purged: the
   markup that used them never made it across, and Instatic strips CSS it
   believes is unused. Re-added with the reviews block itself.
   -------------------------------------------------------------------------- */
.rv-card { background: var(--black); padding: clamp(1.35rem, 2.2vw, 1.9rem); display: grid; gap: .9rem; align-content: start; transition: background .4s ease; }
.rv-card:hover { background: var(--ink-800); }
.rv-card p { color: rgba(255,255,255,.78); font-weight: 300; font-size: .94rem; line-height: 1.75; }
.rv-card footer { display: flex; align-items: center; gap: .7rem; font-size: .85rem; color: #fff; padding-top: .9rem; border-top: 1px solid rgba(255,255,255,.09); }
.rv-card footer i { margin-left: auto; font-style: normal; font-size: .66rem; letter-spacing: .14em; text-transform: uppercase; color: rgba(255,255,255,.58); }
.rv-card:hover .rv-play { background: var(--gold); }
.rv-card:hover .rv-play::after { border-left-color: var(--black); }

/* --------------------------------------------------------------------------
   INVERTED MEDIA QUERY ORDER (fixed 2026-08-18)
   The imported stylesheet emits the min-width:1080px rule for .rv-grid BEFORE
   the min-width:700px one, and the same for .ga-grid at 1100/700. Both match on
   a desktop viewport, specificity is equal, so the LATER (narrower) rule wins
   and a three-column grid renders as two. Instatic re-serialised the registry
   and lost the source order; this file loads after it, so restating the wide
   breakpoints here restores them.
   -------------------------------------------------------------------------- */
@media (min-width: 1080px) { .rv-grid { grid-template-columns: repeat(3, 1fr); } }
@media (min-width: 1100px) { .ga-grid { grid-template-columns: repeat(3, 1fr); } }

/* --------------------------------------------------------------------------
   BAKED DARK-ON-DARK HEADING (fixed 2026-08-18)
   The import resolved .rv-head h3 to a literal color:#0b0b0b, presumably from a
   light-theme context, and that heading sits inside ch-proof, which carries
   data-theme="dark". The result is near-black on near-black: the words
   "What patients say afterwards." were invisible. The local build sets no
   colour there at all and inherits --fg, which the dark theme defines as white,
   so that is what is restored. It is the only baked dark colour inside a dark
   section on the whole site.
   -------------------------------------------------------------------------- */
.ch-proof .rv-head h3 { color: var(--fg); }

/* --------------------------------------------------------------------------
   THE WEBFLOW SYNC (added 2026-08-18)
   The client's edits, brought across from the Webflow build they reviewed
   together: the practice gallery in Chapter 08, the review widget in place of
   the six hand-built cards, and the filmed testimonials.
   -------------------------------------------------------------------------- */

/* Chapter 08 gallery. One wide frame leading a row of four: five landscape
   shots at equal size read as a contact sheet, and the wide one gives the eye
   somewhere to land. Sits on this chapter's dark ground, so the frames take a
   hairline rather than a shadow. */
/* --------------------------------------------------------------------------
   HERO REVEAL, MADE UNCONDITIONAL (2026-08-18)
   [data-anim="hide"] is hidden by the design until the reveal runtime adds
   .wz-ready. That runtime does not run in the Instatic editor canvas, so the
   hero heading, lead and buttons were invisible while editing and only the
   background film showed. The published bundle already forced them visible with
